package com.example.uit067.studentmanagement.repository;

import com.example.uit067.studentmanagement.Student;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.stereotype.Repository;

import java.util.List;

/**
 * Spring Data JPA Repository for the Student entity.
 *
 * Extends JpaRepository to inherit standard CRUD operations, pagination, and sorting:
 * - findAll(), findById(id), save(student), deleteById(id)
 * - findAll(Pageable pageable)
 * - findAll(Sort sort)
 *
 * Derived query methods below are automatically generated by Spring Data JPA
 * at runtime based on the method name convention. No manual SQL or @Query is required.
 */
@Repository
public interface StudentRepository extends JpaRepository<Student, Integer> {

    /**
     * Derived query method: Finds all students with an exact matching name.
     * Equivalent SQL: SELECT * FROM students WHERE name = ?;
     *
     * @param name the exact name to search for
     * @return list of students matching the given name
     */
    List<Student> findByName(String name);

    /**
     * Derived query method: Finds all students whose name contains the specified keyword.
     * Equivalent SQL: SELECT * FROM students WHERE name LIKE '%keyword%';
     *
     * @param keyword the substring to match within student names
     * @return list of students whose names contain the keyword
     */
    List<Student> findByNameContaining(String keyword);

    /**
     * Derived query method: Finds student(s) with the specified email address.
     * Equivalent SQL: SELECT * FROM students WHERE email = ?;
     *
     * @param email the email address to search for
     * @return list of students with the matching email
     */
    List<Student> findByEmail(String email);
}
